// === Tab: getPoints ===
let directions = [
    [1, 0],
    [0, -1],
    [0, 1],
    [-1, 0],
]

function getPoints() {
	let [x, y] = P.startPoint 
	let points = [[x, y]] 
	let edges = {} 
	let xMax = P.innerGrid 
	let yMax = P.innerGrid 

	const getEdges = (x, y) => {
			let key = `${x}-${y}`
			if (!edges[key]) {
					edges[key] = []
			}
			return edges[key]
	}

    let i = 0
    let pointsCount = 0
    let needToPushPoint1 = false
    while (i < P.edgesAttempts && pointsCount < P.edgesMax) {
        let visited = getEdges(x, y)
        let options = [...directions].filter(([xd, yd]) => {
            if (x + xd < 0 || x + xd > xMax) return false
            if (y + yd < 0 || y + yd > yMax) return false
            if (visited.find(([vx, vy]) => vx === x + xd && vy === y + yd)) return false
            return true
        })

        if (options.length === 0) {
            x = Math.floor(Math.random() * (xMax + 1))
            y = Math.floor(Math.random() * (yMax + 1))
            i++
            points.push(false)
            points.push([x, y])
            continue
        }

        if (needToPushPoint1) {
            points.push([x, y])
            needToPushPoint1 = false
            pointsCount++
        }
        let prevX = x
        let prevY = y

        let dir = random(options)
        x += dir[0]
        y += dir[1]
        visited.push([x, y])
        getEdges(x, y).push([prevX, prevY])
        points.push([x, y])
        pointsCount++
        i++

        if (i % P.edgesBreak === 0) {
            points.push(false)
            x = Math.floor(Math.random() * (xMax + 1))
            y = Math.floor(Math.random() * (yMax + 1))
            needToPushPoint1 = true
        }
    }	

		return { points, edges }
}

// === Tab: mySketch ===
let P = {
	tiles: 5,
	padding: 0.2,
	edgesMax: 15,
	edgesAttempts: 20,
	edgesBreak: 4,
	innerGrid: 3,
	startPoint: [1, 1],
	symmetry: 'reflect'
}

let pointsData

function quadrant(points, size) {
	let step = size / P.innerGrid
	strokeWeight(3)
	stroke('#fff')
	for (let i = 1; i < points.length; i++) {
		let p1 = points[i - 1]
		let p2 = points[i]
		if (p1 === false || p2 === false) continue
		let [x1, y1] = p1
		let [x2, y2] = p2
		line(x1 * step, y1 * step, x2 * step, y2 * step)
	}
}

function mirroredQuadrants(points, size) {
	let step = size / 2
	push()
	if (P.symmetry === 'reflect') {
		translate(step, step)
		scale(1, -1)
		quadrant(points, step)
		scale(1, -1)
		quadrant(points, step)
		scale(-1, 1)
		quadrant(points, step)
		scale(1, -1)
		quadrant(points, step)
	} else if (P.symmetry === 'rotate') {
		translate(step, step)
		quadrant(points, step)
		rotate(Math.PI / 2)
		quadrant(points, step)
		rotate(Math.PI / 2)
		quadrant(points, step)
		rotate(Math.PI / 2)
		quadrant(points, step)
	}
	pop()
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	pointsData = []
	for (let i = 0; i < P.tiles ** 2; i++) {
		pointsData.push(getPoints())
	}

	noLoop()
}

function draw() {
	background('#121212')
	let m = max(width, height) * 0.85
	push() 
	translate((width - m) / 2, (height - m) / 2)
	let blockStep = m / P.tiles 
	let padding = blockStep * P.padding 
	let blockSize = blockStep - padding * 2
	pointsData.forEach(({ points }, i) => {
		let x = i % P.tiles 
		let y = floor(i / P.tiles) 
		push() 
		translate(x * blockStep + padding, y * blockStep + padding)
		mirroredQuadrants(points, blockSize)
		pop()
	})
	pop()
}

function windowResized() {
	resizeCanvas(window.innerWidth, window.innerHeight) 
	redraw()
}

function mousePressed() {
	pointsData = []
	for (let i = 0; i < P.tiles ** 2; i++) {
		pointsData.push(getPoints())
	}
	redraw()
}

